//! Lazy projection of counted values/GUIDs and Celebration references. Ordered duplicates preserved.
use crate::{ReadSlot,Error,digest::sha256,wire::{Cursor,Token},session::{SessionError,PAGE_LIMIT}};
use std::ops::Range;
#[derive(Debug,Clone,Copy,PartialEq,Eq)]pub enum DetailKind{CounterValues,CounterGuids,CelebrationGuids}
#[derive(Debug,Clone,PartialEq,Eq)]pub enum DetailRow{Guid{words:[u32;4],span:Range<usize>},Text{utf8_len:u32,digest:[u8;32],span:Range<usize>}}
#[derive(Debug,Clone,PartialEq,Eq)]pub struct DetailPage{pub kind:DetailKind,pub parent:u32,pub is_null:bool,pub total:u32,pub offset:u32,pub rows:Vec<DetailRow>}
fn inner(slot:&ReadSlot,kind:DetailKind,parent:u32,offset:u32,limit:u16)->Result<DetailPage,SessionError>{if limit==0||limit>PAGE_LIMIT{return Err(SessionError::Range)}let index=&slot.index;let raw=&slot.envelope.decoded;let range=match kind{DetailKind::CounterValues|DetailKind::CounterGuids=>{let m=index.counters.iter().find(|m|m.id==parent).ok_or(SessionError::NoDomain)?;m.fields[if kind==DetailKind::CounterValues{1}else{2}].bytes.clone()},DetailKind::CelebrationGuids=>index.celebrations.iter().find(|m|m.id==parent).ok_or(SessionError::NoDomain)?.bytes.clone()};let base=range.start;let bytes=raw.get(range).ok_or(SessionError::Input(Error::Schema))?;let mut c=Cursor::new(bytes);let result=(||->Result<(bool,u32,Vec<DetailRow>),Error>{if kind==DetailKind::CelebrationGuids{if c.array()?!=2||c.int(8,8)?!=8||c.array()?!=2||c.int(0,u32::MAX as i128)?!=parent as i128{return Err(Error::Schema)}}let is_null=c.peek()?==0xc0;if is_null{c.token()?;if kind!=DetailKind::CounterValues||c.pos!=bytes.len(){return Err(Error::Schema)}if offset!=0{return Err(Error::Budget)}return Ok((true,0,Vec::new()))}let total=c.array()? as u32;if offset>total{return Err(Error::Budget)}let end=offset.saturating_add(limit as u32).min(total);let mut rows=Vec::with_capacity((end-offset)as usize);for i in 0..end{let at=c.pos;let item=if kind==DetailKind::CounterValues{let v=match c.token()?{Token::Str(s)=>s,_=>return Err(Error::Schema)};if i<offset{continue}DetailRow::Text{utf8_len:v.len()as u32,digest:sha256(v.as_bytes()),span:base+at..base+c.pos}}else{let mut words=[0;4];for x in &mut words{*x=c.int(0,u32::MAX as i128)? as u32;}if i<offset{continue}DetailRow::Guid{words,span:base+at..base+c.pos}};rows.push(item)}if end==total&&c.pos!=bytes.len(){return Err(Error::Trailing)}Ok((false,total,rows))})();let(is_null,total,rows)=result.map_err(|e|if e==Error::Budget{SessionError::Range}else{SessionError::Input(e)})?;Ok(DetailPage{kind,parent,is_null,total,offset,rows})}
pub fn detail_page(slot:&ReadSlot,kind:DetailKind,parent:u32,offset:u32,limit:u16)->Result<DetailPage,SessionError>{inner(slot,kind,parent,offset,limit)}
